import type { Lang } from './route'

export type SpriteMap<K extends string> = Record<K, HTMLImageElement>

/**
 * A sprite with drawn text (screens, signs, speech bubbles): each language has its own
 * file. The English variant sits next to the original as <name>.en.png, generated by
 * tools/build_props*.py --lang en.
 */
export type LocalizedSprite = Record<Lang, string>
export type SpriteSrc = string | LocalizedSprite

/** Marks a sprite that has text: in English it loads <name>.en.png. */
export const withText = (src: string): LocalizedSprite => ({ pt: src, en: src.replace(/\.png$/, '.en.png') })

/** The image paths of a scene in the page's language. */
export function spritePaths<K extends string>(sprites: Record<K, SpriteSrc>, lang: Lang): Record<K, string> {
  const entries = Object.entries(sprites) as [K, SpriteSrc][]
  return Object.fromEntries(entries.map(([key, src]) => [key, typeof src === 'string' ? src : src[lang]])) as Record<K, string>
}

// One promise per file: the phase that preloaded and the one that draws share the same image.
const cache = new Map<string, Promise<HTMLImageElement>>()

function loadImage(src: string): Promise<HTMLImageElement> {
  let promise = cache.get(src)
  if (!promise) {
    promise = new Promise<HTMLImageElement>((resolve, reject) => {
      const image = new Image()
      image.onload = () => resolve(image)
      image.onerror = () => reject(new Error(`Failed to load ${src}`))
      image.src = src
    }).then(async (image) => {
      // Decode before the first draw; if the browser refuses, the canvas decodes later.
      await image.decode?.().catch(() => undefined)
      return image
    })
    // On failure, drop it from the cache so the next attempt downloads again.
    promise.catch(() => cache.delete(src))
    cache.set(src, promise)
  }
  return promise
}

/** Loads the scene's images before drawing starts. */
export function loadSprites<K extends string>(paths: Record<K, string>): Promise<SpriteMap<K>> {
  const entries = Object.entries(paths) as [K, string][]
  return Promise.all(
    entries.map(([key, src]) => loadImage(src).then((image) => [key, image] as const)),
  ).then((loaded) => Object.fromEntries(loaded) as SpriteMap<K>)
}

/** Interpolates from 0 to 1 within a [start, end] slice of the progress. */
export function segment(progress: number, start: number, end: number) {
  return Math.min(1, Math.max(0, (progress - start) / (end - start)))
}
